-- ACP pilot seed. Contains no personal employee data.

  id,
  code,
  name,
  client_name,
  city,
  status,
  start_date
) values (
  '10000000-0000-0000-0000-000000000001',
  'ACP-001',
  'مشروع ACP التجريبي',
  'عميل تجريبي',
  'الرياض',
  'active',
  current_date
)
on conflict (id) do update set
  name = excluded.name,
  client_name = excluded.client_name,
  city = excluded.city,
  updated_at = now();

on conflict (id) do update set name = excluded.name, updated_at = now();

on conflict (id) do update set name = excluded.name, status = excluded.status, updated_at = now();

on conflict (id) do update set name = excluded.name, location = excluded.location, updated_at = now();
